.inv-parties .p { border: 1px solid #e2e2e2; border-radius: 10px; padding: 10px 12px; }
.inv-parties .k { font-size: 10.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .6px; color: #888; margin-bottom: 4px; }
