/* ---------- 80mm market receipt ---------- */
.rcpt {
    width: 302px;
    background: #fff;
    color: #111;
    font-family: Consolas, "Courier New", monospace;
    font-size: 12.5px;
    line-height: 1.45;
    padding: 18px 14px;
    border: 1px solid var(--mud-palette-lines-default);
