    font-weight: 800;
    letter-spacing: 3px;
}

.rd-logo-box {
    width: 84px;
    height: 84px;
    border: 2px dashed var(--mud-palette-lines-default);
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    overflow: hidden;
    background: var(--mud-palette-background-gray);
    flex: 0 0 auto;
}

.rd-logo-box img { max-width: 100%; max-height: 100%; object-fit: contain; }

.rd-fonts {
