}

/* v220 — the phone pill slims down, and the country drop learns to search. */
.pf-field { border-radius: 12px; margin-bottom: 12px; }
.pf-ccwrap { position: relative; display: flex; }
.pf-ccbtn {
    min-height: 44px;
    padding: 0 9px;
