/* The menu panel */
.ied-menu { flex: 1; display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.ied-search {
    display: flex;
    align-items: center;
    gap: 10px;
    background: var(--mud-palette-background-gray);
