.dc-form { gap: 6px 10px; }
.dc-form .mud-input { font-size: .84rem; }
.dc-form .mud-input-outlined .mud-input-slot { padding-top: 8px !important; padding-bottom: 8px !important; min-height: 38px; }
.dc-form .mud-select .mud-input-slot { min-height: 38px; }
.dc-form .mud-input-label { font-size: .84rem; }
.dc-form .mud-input-label.mud-input-label-inputcontrol.mud-input-label-outlined.mud-shrink,
