/* v693: the discount editor, really small this time. MudBlazor's outlined inputs keep a
   54px box and a 16px floating label whatever the font-size says — so the box, the
   label, the helper and the adornments are all pinned here (Majed: "too big, everything is"). */
.dc-form .mud-input-control { margin: 0 !important; }
.dc-form .mud-input.mud-input-outlined { min-height: 36px !important; }
.dc-form .mud-input.mud-input-outlined:not(:has(textarea)) { height: 36px !important; }
.dc-form input.mud-input-slot { height: 36px !important; padding: 4px 11px !important; font-size: 13px !important; line-height: 1.3 !important; }
.dc-form .mud-select .mud-input-slot { height: 36px !important; min-height: 36px !important; padding: 4px 30px 4px 11px !important; font-size: 13px !important; display: flex; align-items: center; }
.dc-form textarea.mud-input-slot { font-size: 13px !important; padding: 8px 11px !important; min-height: 56px; }
.dc-form .mud-input-label { font-size: 13px !important; }
.dc-form .mud-input-label-outlined { transform: translate(11px, 9px) scale(1) !important; }
.dc-form .mud-input-label-outlined.mud-shrink { transform: translate(11px, -7px) scale(.78) !important; }
.dc-form .mud-input-outlined-border legend { font-size: 10.2px; }
.dc-form .mud-input-control-helper-container, .dc-form .mud-input-helper-text { font-size: 10.5px !important; line-height: 1.25; padding: 0 !important; margin: 1px 0 0 11px !important; }
.dc-form .mud-input-adornment .mud-icon-root, .dc-form .mud-select .mud-icon-root { width: 17px !important; height: 17px !important; }
.dc-form .mud-input-adornment .mud-icon-button, .dc-form .mud-picker .mud-icon-button { padding: 3px !important; }
.dc-form .mud-input-numeric-spin { transform: scale(.8); right: -2px; }
.dc-form .mud-input-numeric-spin .mud-icon-button { padding: 0 !important; }
.dc-form .mud-picker-inline-input .mud-input-adornment { margin: 0 !important; }
.dc-form .mud-switch .mud-typography { font-size: 12.5px !important; }
