  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'><path fill='%236b6259' d='M7 10l5 5 5-5z'/></svg>");
  background-repeat: no-repeat; background-position: right 6px center; background-size: 20px;
