/* ===== RECONNECT OVERLAY v698 — "add better ui for it, and add button reconnect" =====
   The circuit-drop card in all four apps. Blazor only toggles the modal's show/failed
   classes; mf-reconnect.js adds .mf-slow once the rejoin drags on (buttons appear),
   .mf-retrying while Blazor.reconnect() runs and .mf-failed when the server let the
   session go. Everything centred, so RTL needs no mirror. */
#components-reconnect-modal{ background:rgba(28,18,12,.55); backdrop-filter:blur(8px); padding:20px; }
#components-reconnect-modal .mf-reconnect-card{
  position:relative; overflow:hidden; width:min(340px,100%); padding:30px 26px 22px;
  border-radius:26px; gap:0; text-align:center;
  background:var(--mud-palette-surface,#fff);
  box-shadow:0 26px 70px rgba(20,10,4,.38), 0 0 0 1px rgba(255,90,0,.08);
}
#components-reconnect-modal .mf-reconnect-card::before{
  content:""; position:absolute; inset:0 0 auto 0; height:6px;
  background:linear-gradient(90deg,#FF5A00,#FFA400 60%,#FFD08A);
}
.mf-reconnect-halo{ position:relative; width:96px; height:96px; margin:0 auto 18px; display:grid; place-items:center; }
.mf-reconnect-halo span{
  position:absolute; inset:0; border-radius:50%; border:2px solid rgba(255,90,0,.55);
  animation:mfHalo 2.2s ease-out infinite;
}
.mf-reconnect-halo span:nth-child(2){ animation-delay:1.1s; }
.mf-reconnect-halo img{
  width:64px; height:64px; border-radius:50%; background:#fff; padding:10px; box-sizing:border-box;
  box-shadow:0 8px 24px rgba(255,90,0,.28); position:relative; z-index:1;
}
@keyframes mfHalo{ 0%{ transform:scale(.72); opacity:.9; } 100%{ transform:scale(1.35); opacity:0; } }
.mf-reconnect-title{ font-size:18px; font-weight:800; color:#2b1e14; letter-spacing:-.01em; }
#components-reconnect-modal .mf-reconnect-text{ margin-top:6px; font-size:13.5px; line-height:1.45; font-weight:600; color:#7a6d63; min-height:20px; }
.mf-reconnect-dots{ display:flex; justify-content:center; gap:7px; margin:16px 0 4px; height:8px; }
.mf-reconnect-dots i{ width:8px; height:8px; border-radius:50%; background:#FF5A00; opacity:.25; animation:mfDot 1.2s ease-in-out infinite; }
.mf-reconnect-dots i:nth-child(2){ animation-delay:.2s; }
.mf-reconnect-dots i:nth-child(3){ animation-delay:.4s; }
@keyframes mfDot{ 0%,80%,100%{ opacity:.25; transform:translateY(0); } 40%{ opacity:1; transform:translateY(-4px); } }
.mf-reconnect-actions{ display:none; flex-direction:column; gap:8px; margin-top:16px; }
