#components-reconnect-modal .mf-reconnect-btn.ghost{ display:none; }
#components-reconnect-modal.mf-retried .mf-reconnect-btn.ghost,
#components-reconnect-modal.mf-failed .mf-reconnect-btn.ghost{ display:inline-flex; }
/* v699 — the attempt counter under the message ("Attempt 12 of 30 · next try in 4 s"),
