  transition: border-color .15s ease, box-shadow .15s ease;
}
.qm-search:focus-within { border-color: #FF8A3D; box-shadow: 0 0 0 3px rgba(255, 90, 0, .12); }
.qm-search svg { width: 18px; height: 18px; color: #FF5A00; flex: none; }
.qm-search input {
  flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; font-size: 14.5px; color: #1f1812;
  -webkit-appearance: none; appearance: none;
}
.qm-search input::-webkit-search-cancel-button { display: none; }
.qm-search input::placeholder { color: #a39789; }
.qm-search .clr {
  flex: none; width: 26px; height: 26px; border-radius: 50%; border: 0; cursor: pointer;
  background: rgba(60, 40, 20, .08); color: #6b6257; font-size: 12px; font-weight: 800; display: grid; place-items: center;
}
.qm-search .clr:hover { background: rgba(255, 90, 0, .14); color: #c24500; }
.qm-empty {
  display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 34px 16px; text-align: center;
  color: #6b6257; animation: mfFadeUp .25s ease;
}
.qm-empty span { font-size: 34px; }
.qm-empty b { font-size: 15px; color: #2b1e14; }
.qm-empty small { font-size: 12.5px; color: #8a7d70; }
/* v713 — sticky needs the VIEWPORT as its scrollport. With overflow-x set on both html and
   body, body becomes its own (non-scrolling) container and nothing ever sticks. On the
   table-QR page let body overflow normally; html keeps the sideways clip. */
body:has(.qm-head) { overflow-x: visible; overflow-y: visible; }
html:has(.qm-head) { overflow-x: clip; }
/* v714 — table-QR groups: pill row with counts, physical scroll arrows (CSS chevrons, no
   bidi glyphs), faded edges while there is more to scroll, arrows dim at their own end. */
.qm-cats-row { display: flex; align-items: center; gap: 6px; min-width: 0; margin-top: 4px; }
.qm-cats-row .qm-cats { flex: 1; min-width: 0; gap: 8px; padding: 6px 2px 4px !important; margin: 0; scrollbar-width: none; scroll-behavior: smooth; }
.qm-cats-row .qm-cats::-webkit-scrollbar { display: none; }
.qm-cats-row.scrolls .qm-cats { mask-image: linear-gradient(90deg, transparent, #000 14px, #000 calc(100% - 14px), transparent); -webkit-mask-image: linear-gradient(90deg, transparent, #000 14px, #000 calc(100% - 14px), transparent); }
.qm-cats-row.scrolls.at-left .qm-cats { mask-image: linear-gradient(90deg, #000, #000 calc(100% - 14px), transparent); -webkit-mask-image: linear-gradient(90deg, #000, #000 calc(100% - 14px), transparent); }
.qm-cats-row.scrolls.at-right .qm-cats { mask-image: linear-gradient(90deg, transparent, #000 14px, #000); -webkit-mask-image: linear-gradient(90deg, transparent, #000 14px, #000); }
.qm-cats-row .qm-cats button {
  display: inline-flex !important; align-items: center; gap: 6px; height: 36px; padding: 0 14px !important;
  border-radius: 999px !important; border: 1px solid rgba(60, 40, 20, .1) !important; background: #fff !important;
  color: #4a4036 !important; font-size: 13px !important; font-weight: 700 !important; letter-spacing: .01em;
  box-shadow: 0 1px 4px rgba(60, 40, 20, .05); transition: transform .15s ease, box-shadow .15s ease, background .15s ease, color .15s ease !important;
}
.qm-cats-row .qm-cats button em {
  font-style: normal; font-size: 11px; font-weight: 800; line-height: 1; min-width: 20px; height: 20px; padding: 0 6px;
  display: inline-grid; place-items: center; border-radius: 999px; background: rgba(60, 40, 20, .08); color: #6b6257;
}
.qm-cats-row .qm-cats button:active { transform: scale(.96); }
.qm-cats-row .qm-cats button.on {
  background: linear-gradient(135deg, #FF7A1A, #F4511E) !important; border-color: transparent !important; color: #fff !important;
  box-shadow: 0 8px 20px rgba(244, 81, 30, .28);
