.qm-cats-row .qm-cats button.on em { background: rgba(255, 255, 255, .28); color: #fff; }
.qm-cat-arrow {
  display: none; flex: none; width: 32px; height: 32px; border-radius: 50%; border: 1px solid rgba(60, 40, 20, .1);
  background: #fff; cursor: pointer; place-items: center; box-shadow: 0 2px 8px rgba(60, 40, 20, .08); padding: 0;
  transition: opacity .15s ease, transform .15s ease;
