.qm-cats-row.scrolls .qm-cat-arrow { display: grid; }
.qm-cat-arrow i { display: block; width: 8px; height: 8px; border: solid #c24500; border-width: 2.5px 2.5px 0 0; border-radius: 1px; }
.qm-cat-arrow.l i { transform: rotate(-135deg); margin-inline-start: 3px; margin-left: 3px; }
.qm-cat-arrow.r i { transform: rotate(45deg); margin-right: 3px; }
