.ob-card .obc-cust { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.ob-card .obc-name { font-weight: 700; font-size: 13px; }
.ob-card .obc-pay { font-size: 11.5px; color: var(--mud-palette-text-secondary); }
.ob-card .obc-items { display: flex; flex-direction: column; gap: 5px; background: var(--mud-palette-background); border-radius: 10px; padding: 8px 10px; }
.ob-card .obc-items .ob-line { display: flex; gap: 9px; align-items: baseline; }
.ob-card .obc-items .ob-qty { min-width: 19px; height: 19px; line-height: 19px; text-align: center; font-weight: 800; font-size: 11.5px; background: var(--mud-palette-dark); color: #fff; border-radius: 6px; flex: 0 0 auto; }
.ob-card .obc-items .ob-item-name { font-size: 12.5px; }
.ob-card .obc-items .ob-note { font-size: 11px; color: var(--mud-palette-text-secondary); margin-inline-start: 31px; font-style: italic; }
.ob-card .obc-items .ob-order-note { font-size: 12px; margin-top: 3px; }
.ob-card .obc-foot { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-top: 1px; }
.ob-card .obc-total { font-size: 16px; font-weight: 800; }
.ob-card .obc-actions { display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; align-items: center; }
.ob-card .obc-actions .obt-sub { font-size: 11px; color: var(--mud-palette-text-secondary); }

.ob-tag.del{ background:#e9f8ef; color:#177a46; }

.ob-card .obc-actions .mud-button-root { font-size: 12px; padding: 4px 10px; min-height: 30px; }

/* Live orders: compact tab strip */
.ob-tabs .mud-tabs-toolbar { min-height: 34px; }
.ob-tabs .mud-tab { font-size: 11px; font-weight: 700; text-transform: none; letter-spacing: 0; min-height: 34px; padding: 0 10px; min-width: 0; }
