/* v745 — product dialog flags as a list: checkbox, bold label, one-line explanation. */
.mi-flags { display: flex; flex-direction: column; gap: 2px; }
.mi-flag { display: flex; align-items: flex-start; gap: 4px; cursor: pointer; padding: 4px 6px; border-radius: 10px; }
.mi-flag:hover { background: color-mix(in srgb, var(--mud-palette-primary) 6%, transparent); }
.mi-flag .mud-checkbox { margin: 0 !important; }
