.mi-flag > span small { font-size: 11px; color: var(--mud-palette-text-secondary); line-height: 1.3; }

/* v746 — partner guide link under the sign-in form */
.mf-guide-link { display: inline-flex; align-items: center; gap: 6px; margin-top: 12px; font-size: 12.5px; font-weight: 700; color: #C24500; text-decoration: none; }
.mf-guide-link:hover { text-decoration: underline; }

/* v747 — admin contact-message inbox */
.cm-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 8px 0 14px; }
.cm-stat { background: var(--mud-palette-surface); border: 1px solid #f0e7db; border-radius: 14px; padding: 10px 12px; display: grid; gap: 2px; }
.cm-stat b { font-size: 20px; letter-spacing: -.3px; } .cm-stat b small { font-size: 11px; color: #8a8175; font-weight: 700; }
.cm-stat span { font-size: 11px; color: #8a8175; text-transform: uppercase; letter-spacing: .4px; font-weight: 700; }
.cm-list { display: grid; gap: 8px; }
.cm-row { background: var(--mud-palette-surface); border: 1px solid #f0e7db; border-radius: 14px; padding: 10px 12px; cursor: pointer; transition: box-shadow .15s, border-color .15s; }
.cm-row:hover { border-color: #FFB48A; box-shadow: 0 8px 20px rgba(60, 40, 20, .06); }
.cm-head { display: flex; align-items: center; gap: 10px; }
.cm-dot { width: 8px; height: 8px; border-radius: 50%; background: #e3d9cc; flex: none; }
.cm-row.unread .cm-dot { background: #FF5A00; box-shadow: 0 0 0 3px rgba(255, 90, 0, .18); }
.cm-who { flex: 1; min-width: 0; display: grid; }
.cm-who b { font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cm-row.unread .cm-who b { font-weight: 800; }
.cm-who small { font-size: 12px; color: #8a8175; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cm-when { font-size: 12px; color: #8a8175; white-space: nowrap; font-variant-numeric: tabular-nums; }
.cm-body { margin-top: 10px; padding-top: 10px; border-top: 1px dashed #f0e7db; cursor: default; }
.cm-body p { margin: 0 0 8px; white-space: pre-wrap; font-size: 14px; line-height: 1.5; }
.cm-meta { font-size: 11.5px; color: #8a8175; margin-bottom: 8px; }
.cm-actions { display: flex; flex-wrap: wrap; gap: 6px; }
@media (max-width: 600px) { .cm-stats { grid-template-columns: repeat(3, 1fr); gap: 6px; } .cm-stat b { font-size: 17px; } }

/* v748 — SEO heading on the customer home: for crawlers and screen readers, not for the eye */
.mf-seo-h1{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;margin:-1px}

/* v749 — search landing pages (/food-delivery-oman, /cuisines/*, /areas/*) and the crawler footer */
.mf-browse{max-width:1100px;margin:0 auto;padding:18px 16px 60px}
.mf-crumbs{font-size:12.5px;color:var(--mud-palette-text-secondary,#8E8274);margin-bottom:10px}.mf-crumbs a{color:inherit;text-decoration:none}
.mf-browse h1{font-size:clamp(24px,4vw,34px);line-height:1.15;letter-spacing:-.6px;margin:0 0 8px}
.mf-browse-intro{font-size:15.5px;line-height:1.6;color:var(--mud-palette-text-secondary,#5A4E43);max-width:70ch;margin:0 0 14px}
.mf-browse-count{font-size:12px;letter-spacing:1.2px;text-transform:uppercase;color:#8E8274;margin:0 0 10px}.mf-browse-muted{color:#8E8274}
.mf-browse-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}
.mf-browse-card{display:flex;flex-direction:column;text-decoration:none;color:inherit;border:1px solid #EEE6DB;border-radius:18px;overflow:hidden;background:#fff;transition:transform .2s,box-shadow .2s}
.mf-browse-card:hover{transform:translateY(-2px);box-shadow:0 14px 30px rgba(70,35,5,.10)}.mf-browse-card.shut{opacity:.75}
.mf-browse-card .pic{display:block;height:130px;background:#FFE8D9}.mf-browse-card .pic img{width:100%;height:100%;object-fit:cover;display:block}
.mf-browse-card .body{display:flex;flex-direction:column;gap:3px;padding:12px 14px}.mf-browse-card b{font-size:15px}.mf-browse-card .meta{font-size:12.5px;color:#8E8274}
.mf-browse-h2{font-size:18px;margin:26px 0 10px}.mf-browse-links{display:flex;flex-wrap:wrap;gap:8px}.mf-browse-links a{text-decoration:none;font-size:13px;font-weight:700;color:#4F463D;border:1px solid #EEE6DB;background:#FBF8F3;border-radius:999px;padding:6px 12px}
.mf-browse-faq{margin:28px 0 8px}.mf-browse-faq h2{font-size:20px;margin:0 0 8px}.mf-browse-faq details{border:1px solid #EEE6DB;border-radius:12px;padding:10px 14px;margin-bottom:8px;background:#fff}.mf-browse-faq summary{font-weight:700;cursor:pointer}.mf-browse-faq p{margin:8px 0 0;color:#5A4E43;font-size:14px}
.mf-browse-cta{margin-top:26px;font-size:14px}
.mf-seo-footer{padding:20px 16px 90px;border-top:1px solid #EEE6DB;font-size:12.5px}.mf-seo-footer nav{display:flex;flex-wrap:wrap;gap:6px 14px;max-width:1100px;margin:0 auto}.mf-seo-footer a{color:#8E8274;text-decoration:none}

/* v750 — the "Open your business" card holds ONE step now (Google or username+password),
   so the 560px wizard sheet reads as a mostly empty box. A sign-in card is narrow. */
.rg-card{width:min(94vw,420px)}
.rg-card .mf-gsi,.rg-card .mf-gsi > div,.rg-card .mf-gsi iframe{width:100% !important;max-width:100% !important}

/* ============================================================================
   v751 — "Open your business": the page is the pitch as well as the form.
   A warm ember stage with two drifting glows, the promise on the left, and a
   lifted card on the right. On a phone the promise shrinks to a chip and a line
   so the fields stay above the fold. Last block wins over the v213 wizard rules.
   ========================================================================== */
.rg-shell{
    min-height:100vh;min-height:100dvh;
    background:
        radial-gradient(900px 520px at 88% -140px, rgba(255,190,120,.42), transparent 62%),
        radial-gradient(700px 420px at 4% 108%, rgba(255,120,40,.40), transparent 60%),
        linear-gradient(150deg,#2A1A10 0%,#7A2E08 46%,#E8420E 100%);
    display:block;padding:0;position:relative;overflow:hidden;
}
.rg-shell::before,.rg-shell::after{
    content:"";position:absolute;border-radius:50%;filter:blur(90px);pointer-events:none;z-index:0;
    background:radial-gradient(circle,rgba(255,154,77,.55),transparent 70%);
}
.rg-shell::before{width:560px;height:560px;top:-180px;inset-inline-end:-140px;animation:rg-float 18s ease-in-out infinite}
.rg-shell::after{width:460px;height:460px;bottom:-200px;inset-inline-start:-120px;animation:rg-float 22s ease-in-out infinite reverse}
@keyframes rg-float{0%,100%{transform:translate3d(0,0,0) scale(1)}50%{transform:translate3d(0,40px,0) scale(1.08)}}
@media (prefers-reduced-motion:reduce){.rg-shell::before,.rg-shell::after{animation:none}}

.rg-stage{
    position:relative;z-index:1;max-width:1120px;margin:0 auto;
    min-height:100dvh;display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:56px;
    padding:96px 24px 48px;
}
/* ---- the promise ---- */
.rg-pitch{color:#fff;animation:rg-in .6s cubic-bezier(.16,1,.3,1) both}
.rg-chip{
    display:inline-flex;align-items:center;gap:8px;font:800 11.5px/1 inherit;letter-spacing:1.8px;text-transform:uppercase;
    color:#FFF3E8;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.38);border-radius:999px;padding:7px 14px;backdrop-filter:blur(6px);
}
.rg-pitch h1{
    font-size:clamp(30px,3.5vw,46px);line-height:1.06;letter-spacing:-1.4px;font-weight:800;
    margin:18px 0 14px;max-width:16ch;text-wrap:balance;color:#fff;
}
.rg-pitch > p{margin:0 0 22px;font-size:16.5px;line-height:1.6;color:rgba(255,255,255,.86);max-width:46ch}
.rg-points{list-style:none;margin:0 0 22px;padding:0;display:grid;gap:10px}
.rg-points li{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:600;color:rgba(255,255,255,.95)}
.rg-points .ic{
    flex:none;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:800;
    color:#7A2E08;background:#FFD9BF;box-shadow:0 2px 10px rgba(0,0,0,.18);
}
.rg-guide{
    display:inline-flex;align-items:center;gap:8px;text-decoration:none;font-size:14px;font-weight:800;color:#fff;
    border-bottom:1px solid rgba(255,255,255,.45);padding-bottom:2px;
}
.rg-guide:hover{color:#FFD9BF;border-color:#FFD9BF}
.rg-guide span{transition:transform .2s}.rg-guide:hover span{transform:translate(2px,-2px)}

/* ---- the card ---- */
.rg-wrap{width:100%;display:flex;justify-content:center;animation:rg-in .6s .08s cubic-bezier(.16,1,.3,1) both}
.rg-card{
    width:min(94vw,440px);border-radius:26px !important;padding:30px 28px 24px !important;
    background:rgba(255,255,255,.98) !important;border:1px solid rgba(255,255,255,.7) !important;
    box-shadow:0 40px 90px rgba(60,20,0,.34),0 4px 16px rgba(60,20,0,.14) !important;animation:none;
}
.rg-card .rg-top{margin-bottom:22px}
.rg-card .rg-top b{font-size:22px;font-weight:800;letter-spacing:-.5px;color:#1C1712}
.rg-card .mf-gsi{display:flex;justify-content:center;min-height:44px}
.rg-card .mf-gsi > div,.rg-card .mf-gsi iframe{width:100% !important;max-width:100% !important}
.rg-card .mf-or{margin:16px 0}
.rg-card .mud-input-outlined .mud-input-outlined-border{border-radius:14px;border-color:#E9DFD2}
.rg-card .mud-input-outlined-border{border-width:1.5px}
.rg-card .mud-input-root{background:#FCFAF7;border-radius:14px}
.rg-card .mud-input-root input{padding-block:14px}
.rg-acts{margin-top:18px}
.rg-acts .mud-button-root{
    border-radius:16px !important;padding:13px 18px !important;font-weight:800 !important;font-size:15.5px !important;letter-spacing:.2px;
    background:linear-gradient(135deg,#FF7A2A,#E8420E) !important;
    box-shadow:0 14px 30px rgba(232,66,14,.36) !important;transition:transform .18s,box-shadow .18s;
}
.rg-acts .mud-button-root:hover{transform:translateY(-1px);box-shadow:0 18px 38px rgba(232,66,14,.44) !important}
.rg-acts .mud-button-root:active{transform:translateY(0)}
.rg-trust{
    display:flex;flex-wrap:wrap;justify-content:center;gap:8px 18px;margin-top:16px;padding-top:14px;
    border-top:1px solid #F2EAE0;font-size:12.5px;font-weight:700;color:#8E8274;
}
@keyframes rg-in{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rg-pitch,.rg-wrap{animation:none}}

/* ---- phone: the promise becomes a heading, the card leads ---- */
@media (max-width:980px){
    .rg-stage{grid-template-columns:1fr;gap:22px;padding:84px 16px 40px;min-height:auto;align-content:start}
    .rg-pitch{text-align:center}
    .rg-pitch h1{font-size:clamp(24px,6.4vw,30px);margin:12px auto 10px;max-width:22ch}
    .rg-pitch > p,.rg-points,.rg-guide{display:none}
    .rg-card{padding:24px 20px 20px !important}
    .rg-card .rg-top b{font-size:19px}
}

/* v752 — on a phone the form leads and the promise follows: the card sits at the top of
   the screen, the pitch reads underneath it in full (it is below the fold either way,
   so the paragraph, the four points and the guide link come back). */
@media (max-width:980px){
    .rg-stage{padding-top:80px}
    .rg-wrap{order:1}
    .rg-pitch{order:2;margin-top:6px;padding-bottom:8px}
    .rg-pitch > p{display:block;margin:0 auto 20px;max-width:40ch;font-size:15px}
    /* inline-grid let the guide link flow up beside the last bullet — a real grid keeps its own line */
    .rg-points{display:grid;justify-content:center;justify-items:start;text-align:start;gap:9px;margin:0 0 22px}
    .rg-guide{display:inline-flex}
    .rg-pitch h1{font-size:clamp(23px,6vw,28px);margin-top:14px}
}

/* v754 — the shop's own Instagram: connect once, then post a dish or a picture. */
.ig-page{max-width:1120px;margin:0 auto;padding:4px 2px 40px}
.ig-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:14px}
.ig-acct{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid #EEE6DB;border-radius:999px;padding:5px 6px 5px 12px;font-weight:700;font-size:13.5px}
.ig-acct .dot{width:8px;height:8px;border-radius:50%}.ig-acct .dot.ok{background:#1B8A4C}.ig-acct .dot.bad{background:#E0A800}
.ig-card{border:1px solid #EEE6DB;border-radius:18px;padding:18px 20px;background:#fff}
.ig-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,.75fr);gap:16px;align-items:start}
.ig-connect{max-width:640px}
.ig-mark{display:inline-grid;place-items:center;width:46px;height:46px;border-radius:14px;font-size:24px;background:linear-gradient(135deg,#FFDCC4,#FFB07A);margin-bottom:10px}
.ig-steps{margin:10px 0 0;padding-inline-start:20px;color:#5A4E43;font-size:14px;line-height:1.7}
.ig-pick-h{display:block;font:800 11px/1 inherit;letter-spacing:1.4px;text-transform:uppercase;color:#8E8274;margin-bottom:8px}
.ig-thumbs{display:flex;gap:10px;overflow-x:auto;padding-bottom:6px;scrollbar-width:thin}
.ig-thumb{flex:0 0 96px;width:96px;border:2px solid #EEE6DB;background:#fff;border-radius:14px;padding:0;overflow:hidden;cursor:pointer;text-align:center;transition:border-color .15s,transform .15s}
.ig-thumb:hover{transform:translateY(-2px)}.ig-thumb.on{border-color:#FF5A00;box-shadow:0 8px 20px rgba(255,90,0,.22)}
.ig-thumb img{display:block;width:96px;height:96px;object-fit:cover}
.ig-thumb span{display:block;padding:5px 6px;font-size:11px;font-weight:700;color:#4F463D;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ig-thumb.add{display:grid;place-items:center;height:124px;border-style:dashed;color:#8E8274}
.ig-thumb.add .plus{font-size:26px;line-height:1;color:#FF5A00}
.ig-chosen{display:flex;align-items:center;gap:10px;margin-top:10px;background:#FBF8F3;border:1px solid #EEE6DB;border-radius:12px;padding:8px 10px}
.ig-chosen img{width:52px;height:52px;object-fit:cover;border-radius:8px}
.ig-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.ig-tags button{font-size:12px;font-weight:700;color:#4F463D;background:#FBF8F3;border:1px solid #EEE6DB;border-radius:999px;padding:5px 11px;cursor:pointer}
.ig-tags button:hover{border-color:#FF5A00;color:#C44300}
.ig-facts{display:grid;gap:8px;font-size:13.5px}
.ig-facts div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px dashed #F2EAE0;padding-bottom:6px}
.ig-facts span{color:#8E8274}
.ig-recent{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
.ig-recent a{display:block;aspect-ratio:1;border-radius:10px;overflow:hidden;background:#FBF8F3}
.ig-recent img{width:100%;height:100%;object-fit:cover;display:block}
@media (max-width:900px){.ig-grid{grid-template-columns:1fr}.ig-card{padding:14px 14px}}

/* v755 — Settings is a long form of many fields; at the app's default size it reads like a
   poster. One step down for every control ON THIS PAGE only: labels, values, helper lines,
   selects and switches, so a whole section fits on one screen. */
.st-page .mud-input-root,
.st-page .mud-input-root input,
.st-page .mud-input-root textarea,
.st-page .mud-select-input input{font-size:13.5px}
.st-page .mud-input-label,
.st-page .mud-input-label-inputcontrol{font-size:13px}
.st-page .mud-input-helper-text{font-size:11.5px;line-height:1.45}
.st-page .mud-typography-h6{font-size:16px}
.st-page .mud-typography-caption{font-size:11.5px}
.st-page .mud-typography-body1{font-size:13.5px}
.st-page .mud-typography-body2{font-size:12.5px}
.st-page .mud-button-root{font-size:13px}
.st-page .mud-switch-label,.st-page .mud-checkbox .mud-typography{font-size:13px}
.st-page .mud-chip{font-size:11.5px}
.st-page .mud-list-item-text .mud-typography{font-size:13.5px}
.st-page .ig-steps{font-size:12.5px;line-height:1.6}

/* v756 — Settings, second pass: the floating LABEL was still 16px because MudBlazor's own
   label rules are more specific than v755's. These win, and everything drops one more step. */
.st-page .mud-input-label,
.st-page label.mud-input-label,
.st-page .mud-input-label-inputcontrol,
.st-page .mud-input-label-outlined,
.st-page .mud-input-label-animated,
.st-page .mud-input-label-margin-dense{font-size:12.5px !important}
.st-page .mud-input-root,
.st-page .mud-input-root input,
.st-page .mud-input-root textarea,
.st-page .mud-input-slot,
.st-page .mud-select-input input,
.st-page .mud-input-adornment,
.st-page .mud-picker input{font-size:13px !important}
.st-page .mud-input-helper-text{font-size:11px !important}
.st-page .mud-typography-h6{font-size:15.5px !important}
.st-page .mud-button-root{font-size:12.5px !important}
.st-page .mud-switch-label,.st-page .mud-checkbox .mud-typography{font-size:12.5px !important}

/* v757 — the Instagram planner: a picture, a caption, a day and an hour. */
.igp{max-width:1180px;margin:0 auto;padding:4px 2px 40px}
.igp-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:14px}
.igp-card{border:1px solid #EEE6DB;border-radius:20px;padding:18px 20px;background:#fff}
.igp-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:16px;align-items:start}
.igp-empty{text-align:center;padding:40px 20px}
.igp-empty .ic{font-size:34px;display:block;margin-bottom:8px}
.igp-compose{display:grid;grid-template-columns:230px minmax(0,1fr);gap:18px}
.igp-shot{position:relative;width:230px;height:230px;border-radius:18px;overflow:hidden;background:#FBF8F3;border:2px dashed #E3D9CC;display:grid;place-items:center;cursor:pointer;transition:border-color .2s,transform .2s}
.igp-shot:hover{border-color:#FF5A00;transform:translateY(-1px)}
.igp-shot.empty .hint{display:grid;justify-items:center;gap:4px;color:#8E8274;padding:16px;text-align:center}
.igp-shot .plus{font-size:30px;line-height:1;color:#FF5A00}
.igp-shot .hint b{font-size:14px;color:#4F463D}.igp-shot .hint small{font-size:11.5px}
.igp-shot img{width:100%;height:100%;object-fit:cover;display:block}
.igp-shot .x{position:absolute;top:8px;inset-inline-end:8px;width:26px;height:26px;border-radius:50%;border:0;background:rgba(28,23,18,.65);color:#fff;cursor:pointer;font-size:13px;line-height:1}
.igp-lbl{display:block;font:800 10.5px/1 inherit;letter-spacing:1.4px;text-transform:uppercase;color:#8E8274;margin-bottom:6px}
.igp-dishes{display:flex;gap:6px;overflow-x:auto;padding-bottom:4px}
.igp-dishes button{flex:0 0 52px;width:52px;height:52px;padding:0;border:2px solid transparent;border-radius:12px;overflow:hidden;cursor:pointer;background:#FBF8F3}
.igp-dishes button.on{border-color:#FF5A00}
.igp-dishes img{width:100%;height:100%;object-fit:cover;display:block}
.igp-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.igp-tags button{font-size:11.5px;font-weight:700;color:#4F463D;background:#FBF8F3;border:1px solid #EEE6DB;border-radius:999px;padding:4px 10px;cursor:pointer}
.igp-tags button:hover{border-color:#FF5A00;color:#C44300}
.igp-when{display:flex;gap:10px;flex-wrap:wrap}
.igp-quick{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.igp-quick button{font-size:12px;font-weight:700;color:#C44300;background:#FFF2E8;border:1px solid #FFD9BF;border-radius:999px;padding:5px 11px;cursor:pointer}
.igp-quick button:hover{background:#FFE2CE}
.igp-list{display:grid;gap:8px}
.igp-row{display:flex;align-items:center;gap:10px;border:1px solid #EEE6DB;border-radius:14px;padding:8px 10px;background:#fff}
.igp-row.posted{background:#F6FBF7;border-color:#D7EBDD}
.igp-row.failed{background:#FDF6F5;border-color:#F0D7D3}
.igp-row.cancelled{opacity:.6}
.igp-row .th{flex:none;width:46px;height:46px;border-radius:10px;overflow:hidden;background:#FBF8F3}
.igp-row .th img{width:100%;height:100%;object-fit:cover;display:block}
.igp-row .body{flex:1;min-width:0;display:grid;gap:2px}
.igp-row .body b{font-size:13px}
.igp-row .cap{font-size:12px;color:#8E8274;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.igp-row .err{font-size:11.5px;color:#B3261E}
.igp-row .act{display:flex;align-items:center;gap:4px}
.igp-row .state{font-size:10.5px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;padding:3px 8px;border-radius:999px;background:#FFF2E8;color:#C44300}
.igp-row .state.posted{background:#E9F7EE;color:#1B8A4C}
.igp-row .state.failed{background:#FCEBEA;color:#B3261E}
.igp-row .state.cancelled{background:#F2EFEA;color:#8E8274}
@media (max-width:1000px){.igp-grid{grid-template-columns:1fr}}
@media (max-width:640px){.igp-compose{grid-template-columns:1fr}.igp-shot{width:100%;height:210px}}

/* v758 — the product picker behind "All products" on the Instagram pages. */
.pp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;max-height:52vh;overflow:auto;padding:2px}
.pp-card{display:flex;flex-direction:column;text-align:start;border:1px solid #EEE6DB;border-radius:14px;background:#fff;padding:0;overflow:hidden;cursor:pointer;transition:transform .15s,border-color .15s}
.pp-card:hover{transform:translateY(-2px);border-color:#FF5A00}
.pp-card .pic{display:block;height:104px;background:#FBF8F3}
.pp-card .pic img{width:100%;height:100%;object-fit:cover;display:block}
.pp-card .txt{display:grid;gap:2px;padding:8px 10px}
.pp-card .txt b{font-size:13px;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pp-card .txt small{font-size:11px;color:#8E8274;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* v759 — the menu poster: choose dishes on the left, watch the picture build on the right. */
.igm{max-width:1180px;margin:0 auto;padding:4px 2px 40px}
.igm-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:14px}
.igm-card{border:1px solid #EEE6DB;border-radius:20px;padding:18px 20px;background:#fff}
.igm-grid{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:16px;align-items:start}
.igm-row{display:flex;gap:10px;flex-wrap:wrap}
.igm-theme{max-width:190px}
.igm-hint{font-size:11.5px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#8E8274;margin:12px 0 6px}
.igm-items{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:6px;max-height:320px;overflow:auto;padding:2px}
.igm-item{display:flex;align-items:center;gap:8px;border:1px solid #EEE6DB;border-radius:12px;background:#fff;padding:8px 10px;cursor:pointer;text-align:start;transition:border-color .15s,background .15s}
.igm-item:hover{border-color:#FF5A00}
.igm-item.on{border-color:#FF5A00;background:#FFF6EF}
.igm-item:disabled{opacity:.45;cursor:not-allowed}
.igm-item .tick{flex:none;width:20px;height:20px;border-radius:6px;border:1.5px solid #E3D9CC;display:grid;place-items:center;font-size:12px;font-weight:800;color:#fff}
.igm-item.on .tick{background:#FF5A00;border-color:#FF5A00}
.igm-item .nm{flex:1;min-width:0;font-size:13px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.igm-item .pr{font-size:12px;font-weight:800;color:#C44300;white-space:nowrap}
.igm-preview{border-radius:16px;overflow:hidden;background:#FBF8F3;border:1px solid #EEE6DB;aspect-ratio:1080/1350;display:grid;place-items:center}
.igm-preview img{width:100%;height:100%;object-fit:cover;display:block}
.igm-preview .ph{color:#8E8274;font-size:13px;padding:20px;text-align:center}
@media (max-width:1000px){.igm-grid{grid-template-columns:1fr}.igm-preview{max-width:420px;margin:0 auto}}

/* v760 — the Instagram glyph beside the three page titles and in the menu. */
.ig-h5{display:flex;align-items:center;gap:10px}
.ig-h5-ic{width:26px;height:26px;color:#FF5A00;flex:none}
.ig-mark svg,.igp-empty .ic svg{display:block}

/* v761 — the admin "who joined" bell: a count on the app bar, a readable list under it. */
.jb-wrap{position:relative;display:inline-flex}
.jb-count{position:absolute;top:1px;inset-inline-end:1px;min-width:16px;height:16px;padding:0 4px;border-radius:9px;
    background:#E53935;color:#fff;font-size:10.5px;font-weight:800;line-height:16px;text-align:center;pointer-events:none}
.jb-list{min-width:330px;max-width:400px;padding:0!important}
.jb-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px 8px;
    font-size:12px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274}
.jb-new{background:#FF5A00;color:#fff;border-radius:9px;padding:1px 7px;font-size:11px}
.jb-empty{padding:18px 16px 22px;font-size:13px;color:#8E8274;text-align:center}
.jb-row{display:flex;align-items:flex-start;gap:10px;width:100%;padding:10px 14px;border:0;background:none;
    text-align:start;cursor:pointer;border-top:1px solid rgba(0,0,0,.06)}
.jb-row:hover{background:rgba(255,90,0,.06)}
.jb-row.un{background:rgba(255,90,0,.04)}
.jb-ic{flex:none;width:30px;height:30px;border-radius:9px;display:grid;place-items:center;font-size:15px;background:#F3EEE7}
.jb-ic.business{background:#FFE9DB}
.jb-ic.driver{background:#E4F0FF}
.jb-txt{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.jb-txt .t{font-size:13px;font-weight:800;line-height:1.25}
.jb-txt .b{font-size:12px;color:#6B5D4F;line-height:1.35;overflow:hidden;text-overflow:ellipsis}
.jb-when{flex:none;font-size:11px;font-weight:700;color:#9C9082;padding-top:2px}

/* v762 — the assistant report: one row per address, the conversation behind it. */
.bc-wrap{overflow:hidden}
.bc-row{cursor:pointer}
.bc-ip{font-weight:800;font-size:12.5px}
.bc-cc{margin-inline-start:6px;font-size:10.5px;font-weight:800;letter-spacing:.4px;color:#8E8274;
    border:1px solid #E3D9CC;border-radius:6px;padding:0 5px}
.bc-said{display:inline-block;max-width:420px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
    font-size:12.5px;color:#3A322B}
.bc-when{font-size:12px;color:#8E8274;white-space:nowrap}
.bc-dlg-head{display:flex;align-items:center;font-weight:800}
.bc-dlg-count{margin-inline-start:8px;background:#FF5A00;color:#fff;border-radius:9px;padding:1px 8px;font-size:11px}
.bc-thread{display:flex;flex-direction:column;gap:14px;max-height:62vh;overflow:auto}
.bc-session{border:1px solid #EEE6DB;border-radius:14px;padding:10px 12px;background:#FDFBF8}
.bc-session-h{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:800;letter-spacing:.4px;
    text-transform:uppercase;color:#8E8274;margin-bottom:8px}
.bc-bot{background:#FFE9DB;color:#C44300;border-radius:6px;padding:0 6px;letter-spacing:0;text-transform:none}
.bc-lang{border:1px solid #E3D9CC;border-radius:6px;padding:0 5px;letter-spacing:0;text-transform:uppercase}
.bc-turn{padding:6px 0;border-top:1px dashed rgba(0,0,0,.07)}
.bc-turn:first-of-type{border-top:0}
.bc-said-row,.bc-reply-row{display:flex;gap:8px;font-size:13px;line-height:1.45;margin:2px 0}
.bc-said-row .who,.bc-reply-row .who{flex:none;font-size:10.5px;font-weight:800;letter-spacing:.4px;
    text-transform:uppercase;padding-top:3px;min-width:58px}
.bc-said-row .who{color:#1E88E5}
.bc-reply-row{color:#6B5D4F}
.bc-reply-row .who{color:#C44300}
.bc-page{font-size:11px;color:#9C9082;margin-top:2px}
@media (max-width:700px){.bc-said{max-width:190px}}

/* v763 — the till page on the customer site: a business pitch inside a consumer app. */
.mf-pos{max-width:1080px;margin:0 auto;padding:18px 16px 56px}
.mf-pos-hero{padding:18px 0 6px;border-bottom:1px solid rgba(0,0,0,.08);margin-bottom:26px}
.mf-pos-hero h1{font-size:clamp(26px,4.4vw,40px);line-height:1.15;margin:6px 0 12px;font-weight:800}
.mf-pos-hero .lede{font-size:clamp(15px,1.9vw,18px);line-height:1.6;color:#4A4038;max-width:62ch;margin:0 0 12px}
.mf-pos-hero .free{display:inline-block;background:#FFF1E6;color:#C44300;border:1px solid #FFD9BF;
    border-radius:999px;padding:5px 14px;font-size:13px;font-weight:800;margin:0 0 16px}
.mf-pos .cta{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0 0}
.mf-pos .cta a{display:inline-block;border-radius:12px;padding:11px 20px;font-size:14px;font-weight:800;text-decoration:none}
.mf-pos .cta a.go{background:#FF5A00;color:#fff}
.mf-pos .cta a.go:hover{background:#E14F00}
.mf-pos .cta a.ghost{border:1.5px solid #E3D9CC;color:#3A322B}
.mf-pos .cta a.ghost:hover{border-color:#FF5A00;color:#C44300}
.mf-pos-h2{font-size:clamp(19px,2.6vw,26px);font-weight:800;margin:32px 0 16px}
.mf-pos-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}
.mf-pos-card{border:1px solid #EEE6DB;border-radius:16px;padding:16px 18px;background:#fff}
.mf-pos-card h3{font-size:15.5px;font-weight:800;margin:0 0 7px;color:#C44300}
.mf-pos-card p{font-size:13.5px;line-height:1.6;color:#4A4038;margin:0}
.mf-pos-price{margin-top:34px;border:1px solid #FFD9BF;background:#FFF8F3;border-radius:18px;padding:20px 22px}
.mf-pos-price h2{font-size:20px;font-weight:800;margin:0 0 8px}
.mf-pos-price p{font-size:14px;line-height:1.6;color:#4A4038;margin:0;max-width:62ch}
.mf-pos-faq{margin-top:34px}
.mf-pos-faq h2{font-size:clamp(19px,2.6vw,26px);font-weight:800;margin:0 0 12px}
.mf-pos-faq details{border-top:1px solid rgba(0,0,0,.08);padding:12px 2px}
.mf-pos-faq summary{cursor:pointer;font-size:14.5px;font-weight:800;list-style:none}
.mf-pos-faq summary::-webkit-details-marker{display:none}
.mf-pos-faq summary::after{content:"+";float:inline-end;color:#FF5A00;font-weight:800}
.mf-pos-faq details[open] summary::after{content:"–"}
.mf-pos-faq p{font-size:13.5px;line-height:1.65;color:#4A4038;margin:8px 0 2px;max-width:70ch}
.mf-pos-also{margin-top:34px;border-top:1px solid rgba(0,0,0,.08);padding-top:20px}
.mf-pos-also h2{font-size:19px;font-weight:800;margin:0 0 8px}
.mf-pos-also p{font-size:14px;line-height:1.6;color:#4A4038;margin:0;max-width:62ch}

/* v764 — the kitchen display. Its own dark world: this screen is read from two metres
   away, in a hot room, by someone holding a pan. Everything is bigger and calmer than
   the rest of the portal, and the only colours that carry meaning are the heat edges. */
.kds-root{--k-bg:#0B0D10;--k-card:#151A21;--k-line:#222A34;--k-ink:#F2F5F8;--k-dim:#8A97A6;
    --k-fresh:#2ED47A;--k-warn:#FFB020;--k-late:#FF4D4D;--k-on:#FF7A2A;
    position:fixed;inset:0;display:flex;flex-direction:column;background:var(--k-bg);color:var(--k-ink);
    font-family:Manrope,system-ui,"Segoe UI",Arial,sans-serif;overflow:hidden}

.kds-bar{flex:none;display:flex;align-items:center;gap:18px;padding:10px 16px;background:#0E1218;
    border-bottom:1px solid var(--k-line);flex-wrap:wrap}
.kds-brand{display:flex;align-items:center;gap:9px;font-size:15px;font-weight:800;letter-spacing:.3px}
.kds-brand .dot{width:9px;height:9px;border-radius:50%;background:var(--k-fresh);box-shadow:0 0 10px var(--k-fresh)}
.kds-brand .dot.off{background:var(--k-late);box-shadow:0 0 10px var(--k-late)}
.kds-brand .store{color:var(--k-dim);font-weight:600;font-size:13px}

.kds-stations{display:flex;gap:6px;flex-wrap:wrap}
.kds-stations button{background:#161C24;border:1px solid var(--k-line);color:var(--k-dim);border-radius:10px;
    padding:6px 13px;font-size:12.5px;font-weight:800;cursor:pointer;font-family:inherit}
.kds-stations button.on{background:var(--k-on);border-color:var(--k-on);color:#fff}

.kds-stats{display:flex;gap:16px;margin-inline-start:auto;font-size:12.5px;color:var(--k-dim);font-weight:700}
.kds-stats b{color:var(--k-ink);font-size:16px;font-weight:800;margin-inline-end:4px}
.kds-stats .late b{color:var(--k-late)}

.kds-tools{display:flex;align-items:center;gap:6px}
.kds-tools button,.kds-tools a{background:#161C24;border:1px solid var(--k-line);color:var(--k-dim);
    border-radius:10px;width:34px;height:34px;display:grid;place-items:center;font-size:14px;cursor:pointer;
    text-decoration:none;font-family:inherit}
.kds-tools button.on{color:var(--k-ink);border-color:#37414F}
.kds-tools .clock{font-size:15px;font-weight:800;margin-inline-start:6px;font-variant-numeric:tabular-nums}

.kds-lanes{flex:1;display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--k-line);min-height:0}
.kds-lane{background:var(--k-bg);display:flex;flex-direction:column;min-height:0}
.kds-lane h2{flex:none;margin:0;padding:10px 16px;font-size:11.5px;font-weight:800;letter-spacing:1.2px;
    text-transform:uppercase;color:var(--k-dim);border-bottom:1px solid var(--k-line);display:flex;gap:8px;align-items:center}
.kds-lane h2 span{background:#1B222B;border-radius:8px;padding:1px 8px;font-size:12px;color:var(--k-ink)}
.kds-lane.on h2{color:var(--k-on)}
.kds-tickets{flex:1;min-height:0;overflow:auto;padding:12px;display:grid;
    grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px;align-content:start}

.kds-ticket{background:var(--k-card);border:1px solid var(--k-line);border-radius:14px;overflow:hidden;
    display:flex;flex-direction:column;border-top:4px solid var(--k-fresh)}
.kds-ticket.warn{border-top-color:var(--k-warn)}
.kds-ticket.late{border-top-color:var(--k-late)}
.kds-ticket.late header .age{color:var(--k-late);animation:kdsPulse 1.6s ease-in-out infinite}
@keyframes kdsPulse{0%,100%{opacity:1}50%{opacity:.45}}
@media (prefers-reduced-motion:reduce){.kds-ticket.late header .age{animation:none}}

.kds-ticket header{display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid var(--k-line)}
.kds-ticket .no{font-size:15px;font-weight:800}
.kds-ticket .kind{font-size:10.5px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;
    background:#1B222B;color:var(--k-dim);border-radius:7px;padding:2px 7px;white-space:nowrap;
    overflow:hidden;text-overflow:ellipsis;max-width:120px}
.kds-ticket .kind.dinein{background:#22302B;color:#6FE0A6}
.kds-ticket .kind.pickup{background:#2B2740;color:#B7A6F5}
.kds-ticket .age{margin-inline-start:auto;font-size:15px;font-weight:800;font-variant-numeric:tabular-nums;color:var(--k-dim)}

.kds-lines{list-style:none;margin:0;padding:6px 0;flex:1}
.kds-lines li{display:flex;align-items:baseline;gap:9px;padding:7px 12px;cursor:pointer;flex-wrap:wrap}
.kds-lines li:hover{background:#1A212A}
.kds-lines .q{flex:none;min-width:24px;height:24px;border-radius:7px;background:#232C37;color:var(--k-ink);
    display:grid;place-items:center;font-size:13px;font-weight:800}
.kds-lines .nm{font-size:15px;font-weight:700;line-height:1.3;flex:1;min-width:0}
.kds-lines .note{flex-basis:100%;margin-inline-start:33px;font-size:12.5px;color:var(--k-warn);font-weight:600}
.kds-lines li.off .nm{text-decoration:line-through;color:var(--k-dim);font-weight:500}
.kds-lines li.off .q{background:#1A212A;color:var(--k-dim)}
.kds-lines li.off .note{color:var(--k-dim);text-decoration:line-through}

.kds-order-note{margin:0;padding:8px 12px;background:#26200F;color:#FFD48A;font-size:12.5px;font-weight:700;line-height:1.4}
.kds-when{margin:0;padding:6px 12px;color:var(--k-dim);font-size:12px;font-weight:700}

.kds-bump{flex:none;border:0;border-top:1px solid var(--k-line);background:#1B232D;color:var(--k-ink);
    padding:12px;font-size:13.5px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;cursor:pointer;font-family:inherit}
.kds-bump:hover{background:#222C38}
.kds-ticket.on .kds-bump{background:var(--k-on);color:#fff}
.kds-ticket.on .kds-bump:hover{background:#E96C20}
.kds-bump:disabled{opacity:.5;cursor:default}

.kds-done{flex:none;display:flex;align-items:center;gap:8px;padding:8px 16px;background:#0E1218;
    border-top:1px solid var(--k-line);overflow-x:auto}
.kds-done .lbl{font-size:10.5px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--k-dim);white-space:nowrap}
.kds-done button{background:#161C24;border:1px solid var(--k-line);color:var(--k-dim);border-radius:9px;
    padding:5px 11px;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap;font-family:inherit}
.kds-done button:hover{border-color:var(--k-on);color:var(--k-ink)}
.kds-done button b{color:var(--k-ink);margin-inline-end:5px}

.kds-empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;
    color:var(--k-dim);font-size:16px;font-weight:700}
.kds-empty .big{font-size:52px}
.kds-empty small{font-size:13px;font-weight:500;color:#5D6975}
.kds-empty .sp{width:26px;height:26px;border-radius:50%;border:3px solid #222A34;border-top-color:var(--k-on);
    animation:kdsSpin .8s linear infinite}
@keyframes kdsSpin{to{transform:rotate(360deg)}}

@media (max-width:900px){
    .kds-lanes{grid-template-columns:1fr;grid-template-rows:1fr 1fr}
    .kds-stats{width:100%;margin-inline-start:0;order:5}
}

/* v765 — kitchen display, second pass: the age is the number a cook reads first, the
   table has to carry across the room, and an empty lane should say so rather than
   look broken. */
.kds-ticket .age{font-size:19px;letter-spacing:.5px}
.kds-ticket.warn .age{color:var(--k-warn)}
.kds-ticket .no{font-size:14px;color:var(--k-dim);font-weight:700}
.kds-ticket .kind{font-size:12px;padding:3px 9px;max-width:150px}
.kds-lane-empty{grid-column:1/-1;margin:26px 0 0;text-align:center;color:#4C5765;font-size:13px;font-weight:700}

/* v766 — the currency row in Settings: pick a symbol, or type one, and see it at once. */
.st-cur{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.st-cur-pick{max-width:260px}
.st-cur-own{max-width:130px}
.st-cur-eg{font-size:12.5px;color:#8E8274;font-weight:700}
.st-cur-eg b{color:#C44300;margin-inline-start:4px;font-size:14px}

/* v767 — show the whole address. An IPv4 fits in a narrow column; an IPv6 is up to
   thirty-nine characters and was being cut off with an ellipsis, which hides the only
   thing that identifies the visitor. It now wraps in place instead of being truncated. */
.vis-row{ grid-template-columns:18px minmax(150px,210px) minmax(90px,1fr) minmax(110px,2fr) 54px 54px 92px; }
.vis-ip{
  white-space:normal;
  overflow:visible;
  text-overflow:clip;
  overflow-wrap:anywhere;
  word-break:break-all;
  line-height:1.25;
  font-size:.78rem;
}
@media (max-width: 800px){
  .vis-row{ grid-template-columns:18px 1fr 60px; }
}
/* The assistant report shows the same addresses, and needs the same room. */
.bc-ip{ white-space:normal; overflow-wrap:anywhere; word-break:break-all; line-height:1.3; display:inline-block; max-width:230px; }
.bc-dlg-head .mf-ltr{ overflow-wrap:anywhere; word-break:break-all; }

/* v768 — the business note at the foot of the customer home page. Quiet on purpose: a
   diner should scroll past it, a shop owner should find it. */
.mf-home-pos{max-width:760px;margin:34px auto 8px;padding:22px 20px;border:1px solid #EEE6DB;
    border-radius:18px;background:#FFFBF7}
.mf-home-pos h2{font-size:17px;font-weight:800;margin:0 0 8px;color:#1C1712}
.mf-home-pos p{font-size:13.5px;line-height:1.65;color:#5A4E42;margin:0}
.mf-home-pos .links{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}
.mf-home-pos .links a{font-size:13px;font-weight:800;text-decoration:none;color:#C44300;
    border:1.5px solid #FFD9BF;border-radius:11px;padding:8px 14px;background:#fff}
.mf-home-pos .links a:hover{border-color:#FF5A00;background:#FFF3EA}

/* v770 — waste: a cost, a cause, and the log behind them. Recording is the loudest thing
   on the page because a page that is slow to use gets used once. */
.wa{max-width:1180px;margin:0 auto;padding:2px 2px 40px}
.wa-stats{display:grid;grid-template-columns:1.3fr 1fr 1fr auto;gap:12px;align-items:stretch;margin-bottom:14px}
.wa-stat{border:1px solid #EEE6DB;border-radius:16px;padding:14px 16px;background:#fff;display:flex;flex-direction:column;gap:2px}
.wa-stat.lead{background:linear-gradient(135deg,#FFF6EF,#fff)}
.wa-stat .lbl{font-size:11px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274}
.wa-stat b{font-size:24px;font-weight:800;line-height:1.15}
.wa-stat b.bad{color:#C62828}
.wa-stat .sub{font-size:12px;color:#8E8274}
.wa-range{display:flex;flex-direction:column;gap:6px;justify-content:center}
.wa-range button{border:1px solid #EEE6DB;background:#fff;border-radius:10px;padding:6px 14px;font-size:12.5px;
    font-weight:800;color:#6B5D4F;cursor:pointer;font-family:inherit;white-space:nowrap}
.wa-range button.on{background:#FF5A00;border-color:#FF5A00;color:#fff}

.wa-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:start}
.wa-card{border:1px solid #EEE6DB;border-radius:18px;padding:16px 18px;background:#fff}
.wa-card h3{font-size:14px;font-weight:800;margin:0 0 10px;letter-spacing:.2px}
.wa-empty{font-size:13px;color:#8E8274;margin:6px 0 2px}

.wa-kind{display:flex;gap:8px}
.wa-kind button{flex:1;border:1.5px solid #EEE6DB;background:#fff;border-radius:12px;padding:9px;font-size:13px;
    font-weight:800;color:#6B5D4F;cursor:pointer;font-family:inherit}
.wa-kind button.on{border-color:#FF5A00;background:#FFF6EF;color:#C44300}
.wa-qty{display:flex;align-items:center;gap:10px}
.wa-qty .unit{font-size:13px;font-weight:800;color:#8E8274;min-width:44px}
.wa-hint{font-size:11px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274;margin:14px 0 7px}
.wa-reasons{display:flex;flex-wrap:wrap;gap:7px}
.wa-reasons button{border:1px solid #EEE6DB;background:#fff;border-radius:999px;padding:6px 13px;font-size:12.5px;
    font-weight:700;color:#5A4E42;cursor:pointer;font-family:inherit}
.wa-reasons button.on{background:#1C1712;border-color:#1C1712;color:#fff}
.wa-cost{margin:12px 0 0;font-size:13px;color:#5A4E42}
.wa-cost b{color:#C62828;font-size:15px;margin-inline-start:4px}
.wa-foot{margin:9px 0 0;font-size:11.5px;color:#9C9082;line-height:1.5}

.wa-bar{display:grid;grid-template-columns:120px 1fr 78px;gap:9px;align-items:center;padding:5px 0}
.wa-bar .nm{font-size:12.5px;font-weight:700}
.wa-bar .track{height:9px;border-radius:5px;background:#F3EDE4;overflow:hidden}
.wa-bar .fill{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,#FFB020,#E53935)}
.wa-bar .val{font-size:12.5px;font-weight:800;text-align:end;color:#C62828}

.wa-items{display:flex;flex-direction:column}
.wa-item{display:grid;grid-template-columns:1fr auto auto;gap:10px;padding:7px 0;border-top:1px solid #F5EFE7;font-size:12.5px}
.wa-item:first-child{border-top:0}
.wa-item .nm{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wa-item .qt{color:#8E8274}
.wa-item .val{font-weight:800;color:#C62828;min-width:64px;text-align:end}

.wa-log{display:flex;flex-direction:column}
.wa-row{display:grid;grid-template-columns:104px 1fr 92px 84px 150px 34px;gap:10px;align-items:center;
    padding:9px 0;border-top:1px solid #F5EFE7}
.wa-row:first-child{border-top:0}
.wa-row .rsn{font-size:10.5px;font-weight:800;letter-spacing:.3px;text-transform:uppercase;text-align:center;
    border-radius:8px;padding:3px 6px;background:#F3EDE4;color:#6B5D4F}
.wa-row .rsn.spoiled,.wa-row .rsn.expired{background:#FDECEA;color:#C62828}
.wa-row .rsn.broken{background:#FFF3E0;color:#B26A00}
.wa-row .rsn.staff,.wa-row .rsn.training{background:#E8F1FB;color:#1565C0}
.wa-row .nm{font-size:13px;font-weight:700;min-width:0}
.wa-row .nm small{display:block;font-size:11.5px;font-weight:500;color:#8E8274}
.wa-row .qt{font-size:12.5px;color:#6B5D4F}
.wa-row .val{font-size:13px;font-weight:800;color:#C62828}
.wa-row .who{font-size:11.5px;color:#9C9082;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wa-row .undo{border:1px solid #EEE6DB;background:#fff;border-radius:9px;width:30px;height:30px;cursor:pointer;
    color:#8E8274;font-size:14px;font-family:inherit}
.wa-row .undo:hover{border-color:#FF5A00;color:#C44300}

@media (max-width:980px){
    .wa-stats{grid-template-columns:1fr 1fr}
    .wa-range{flex-direction:row;grid-column:1/-1}
    .wa-grid{grid-template-columns:1fr}
    .wa-row{grid-template-columns:88px 1fr 78px 30px}
    .wa-row .who{display:none}
}

/* v771 — warehouses: a MAP of the places stock is kept. Each place is a node the owner
   drags into position, wearing the icon they picked; a curved line from one node to the
   next says "this feeds that". Below the map: what the chosen place holds, a move
   composer, and the log of moves. */
.wh{max-width:1180px;margin:0 auto;padding:2px 2px 40px}

.whm-bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px}
.whm-add{border:0;background:#1C1712;color:#fff;border-radius:12px;padding:10px 16px;font-size:13px;
    font-weight:800;cursor:pointer;font-family:inherit}
.whm-add:hover{background:#FF5A00}
.whm-pool{display:flex;align-items:center;gap:8px;border:1.5px dashed #D9CFC2;background:#fff;border-radius:12px;
    padding:8px 14px;cursor:pointer;font-family:inherit;color:#5A4E42}
.whm-pool .nm{font-size:13px;font-weight:800;color:#1C1712}
.whm-pool .meta{font-size:11.5px;color:#8E8274}
.whm-pool.on{border-style:solid;border-color:#FF5A00;background:#FFF6EF}
.whm-hint{margin-inline-start:auto;font-size:11.5px;color:#9C9082}

/* The drawing is always 1000x520; the wrapper scales it to the screen (never below 0.72, after
   which it pans sideways). Empty ground pans, nodes drag. */
.whm-wrap{position:relative;overflow-x:auto;overflow-y:hidden;border:1.5px solid #EEE6DB;border-radius:22px;
    background:#FDFBF8;-webkit-overflow-scrolling:touch}
.whm-canvas{position:relative;width:1000px;height:520px;transform-origin:0 0;
    background:#FDFBF8 radial-gradient(#E6DDD0 1.1px,transparent 1.2px) 0 0/22px 22px;touch-action:pan-x;user-select:none}
.whm-canvas.linking{box-shadow:inset 0 0 0 3px #FFD9BF}
.whm-node{touch-action:none}
.whm-lines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.whm-lines path{fill:none;stroke:#B9AC9C;stroke-width:2;stroke-linecap:round;
    stroke-dasharray:7 6;animation:whm-flow 1.4s linear infinite}
.whm-lines marker path{fill:#B9AC9C;stroke:none;animation:none}
@keyframes whm-flow{to{stroke-dashoffset:-13}}
@media (prefers-reduced-motion:reduce){.whm-lines path{animation:none}}

.whm-node{position:absolute;transform:translate(-50%,-50%);display:grid;grid-template-columns:auto 1fr;gap:0 10px;
    align-items:center;min-width:176px;max-width:230px;background:#fff;border:1.5px solid #EEE6DB;border-radius:18px;
    padding:10px 12px 10px 10px;cursor:grab;box-shadow:0 6px 18px -12px rgba(28,23,18,.35);transition:box-shadow .15s,border-color .15s}
.whm-node:hover{border-color:#FFD9BF;box-shadow:0 12px 26px -14px rgba(28,23,18,.45)}
.whm-node.on{border-color:#FF5A00;box-shadow:0 0 0 3px #FFE9DB,0 12px 26px -14px rgba(28,23,18,.45)}
.whm-node.src{border-color:#1C1712;box-shadow:0 0 0 3px #E3D9CC}
.whm-node.drag{cursor:grabbing;transition:none;z-index:5;box-shadow:0 22px 40px -18px rgba(28,23,18,.55)}
.whm-canvas.linking .whm-node:not(.src){cursor:crosshair}
.whm-ic{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:#FFF1E6;color:#C44300}
.whm-ic .mud-icon-root{font-size:26px;width:26px;height:26px}
.whm-node.i-factory .whm-ic{background:#EEF0F6;color:#3D4A6B}
.whm-node.i-truck .whm-ic{background:#FFF4D6;color:#9A6A00}
.whm-node.i-store .whm-ic{background:#E9F5EC;color:#1E7A3C}
.whm-node.i-restaurant .whm-ic{background:#FFE9DB;color:#C44300}
.whm-node.i-kitchen .whm-ic{background:#FFEDE0;color:#B44A00}
.whm-node.i-cold .whm-ic{background:#E6F3FB;color:#1266A6}
.whm-node.i-freezer .whm-ic{background:#E3F0FA;color:#0E4F86}
.whm-node.i-bar .whm-ic{background:#F3E8F8;color:#6B2E8F}
.whm-node.i-customers .whm-ic{background:#E9F5EC;color:#1E7A3C}
.whm-body{min-width:0}
.whm-body .nm{display:flex;align-items:center;gap:5px;font-size:13.5px;font-weight:800;color:#1C1712;min-width:0}
.whm-body .nm .t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.whm-body .nm em{flex:none}
.whm-body .nm em{font-style:normal;font-size:9.5px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;
    color:#C44300;background:#FFE9DB;border-radius:6px;padding:1px 5px;margin-inline-start:5px;vertical-align:middle}
.whm-body .meta{font-size:11px;color:#8E8274;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.whm-body .val{font-size:13px;font-weight:800;color:#1C1712;margin-top:1px}
.whm-tools{position:absolute;top:-13px;inset-inline-end:10px;display:flex;gap:4px;opacity:0;transition:opacity .15s}
.whm-node:hover .whm-tools,.whm-node.on .whm-tools,.whm-node.src .whm-tools,.whm-tools:has(.on){opacity:1}
.whm-tools button{width:26px;height:26px;border-radius:9px;border:1px solid #EEE6DB;background:#fff;color:#8E8274;
    cursor:pointer;display:grid;place-items:center;padding:0;font-family:inherit;box-shadow:0 3px 8px -4px rgba(28,23,18,.4)}
.whm-tools button:hover{border-color:#FF5A00;color:#C44300}
.whm-tools button.on{background:#1C1712;border-color:#1C1712;color:#fff}
.whm-tools .mud-icon-root{font-size:16px;width:16px;height:16px}
@media (hover:none){.whm-tools{opacity:1}}

.whm-lbl{position:absolute;transform:translate(-50%,-50%);border:1px solid #E3D9CC;background:#fff;border-radius:999px;
    padding:3px 8px 3px 10px;font-size:10.5px;font-weight:800;color:#6B5D4F;cursor:pointer;font-family:inherit;
    display:flex;align-items:center;gap:5px;white-space:nowrap;z-index:2}
.whm-lbl .x{color:#B9AC9C;font-size:12px}
.whm-lbl:hover{border-color:#C44300;color:#C44300}
.whm-lbl:hover .x{color:#C44300}

.whm-empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
    gap:8px;color:#8E8274;text-align:center;padding:20px}
.whm-empty p{font-size:13.5px;max-width:360px;margin:0 0 6px}
.whm-linkhint{position:sticky;bottom:14px;margin:-46px auto 0;width:max-content;max-width:94%;display:flex;align-items:center;gap:12px;
    background:#1C1712;color:#fff;border-radius:999px;padding:9px 10px 9px 16px;font-size:12.5px;font-weight:700;
    white-space:nowrap;z-index:3}
.whm-linkhint button{border:0;background:#fff;color:#1C1712;border-radius:999px;padding:5px 11px;font-size:11.5px;
    font-weight:800;cursor:pointer;font-family:inherit}

.wh-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:start;margin-top:14px}
.wh-card{border:1px solid #EEE6DB;border-radius:18px;padding:16px 18px;background:#fff}
.wh-card h3{font-size:14px;font-weight:800;margin:0 0 10px}
.wh-head{display:flex;align-items:center;justify-content:space-between;gap:10px}
.wh-head h3{margin:0}
.wh-head .tools{display:flex;gap:6px}
.wh-head .tools button{border:1px solid #EEE6DB;background:#fff;border-radius:9px;width:30px;height:30px;
    cursor:pointer;color:#8E8274;font-size:13px;font-family:inherit}
.wh-head .tools button:hover{border-color:#FF5A00;color:#C44300}
.wh-empty{font-size:13px;color:#8E8274;margin:10px 0 2px}

.wh-rows{display:flex;flex-direction:column;max-height:340px;overflow:auto;margin-top:8px}
.wh-row{display:grid;grid-template-columns:1fr auto auto;gap:10px;padding:7px 0;border-top:1px solid #F5EFE7;font-size:12.5px}
.wh-row:first-child{border-top:0}
.wh-row .nm{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wh-row .qt{color:#6B5D4F;white-space:nowrap}
.wh-row .val{font-weight:800;min-width:66px;text-align:end}

.wh-move{display:grid;grid-template-columns:1fr 24px 1fr;gap:8px;align-items:center}
.wh-move .arrow{text-align:center;color:#8E8274;font-size:15px}
.wh-hint{font-size:11px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274;margin:14px 0 6px}
.wh-pick{display:flex;flex-direction:column;max-height:300px;overflow:auto;border:1px solid #F3EDE4;border-radius:12px}
.wh-pick-row{display:grid;grid-template-columns:1fr auto 84px;gap:9px;align-items:center;padding:7px 10px;
    border-top:1px solid #F5EFE7}
.wh-pick-row:first-child{border-top:0}
.wh-pick-row.on{background:#FFF6EF}
.wh-pick-row .nm{font-size:12.5px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wh-pick-row .have{font-size:11.5px;color:#8E8274;white-space:nowrap}
.wh-pick-row input{width:100%;border:1px solid #E3D9CC;border-radius:9px;padding:5px 8px;font-size:12.5px;
    font-weight:700;font-family:inherit;text-align:end}
.wh-pick-row input:focus{outline:none;border-color:#FF5A00}

.wh-kinds{display:flex;flex-wrap:wrap;gap:7px}
.wh-kinds button{border:1px solid #EEE6DB;background:#fff;border-radius:999px;padding:6px 13px;font-size:12.5px;
    font-weight:700;color:#5A4E42;cursor:pointer;font-family:inherit}
.wh-kinds button.on{background:#1C1712;border-color:#1C1712;color:#fff}
.wh-icons{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}
.wh-icons button{border:1.5px solid #EEE6DB;background:#fff;border-radius:14px;padding:9px 4px 7px;cursor:pointer;
    font-family:inherit;display:flex;flex-direction:column;align-items:center;gap:4px;color:#5A4E42}
.wh-icons button span{font-size:10.5px;font-weight:700;white-space:nowrap}
.wh-icons button .mud-icon-root{font-size:24px;width:24px;height:24px}
.wh-icons button:hover{border-color:#FFD9BF}
.wh-icons button.on{border-color:#FF5A00;background:#FFF6EF;color:#C44300}

.wh-log{display:flex;flex-direction:column}
.wh-move-row{display:grid;grid-template-columns:230px 1fr 84px 140px;gap:10px;align-items:center;padding:9px 0;
    border-top:1px solid #F5EFE7}
.wh-move-row:first-child{border-top:0}
.wh-move-row .route{font-size:12.5px;color:#6B5D4F}
.wh-move-row .route b{color:#1C1712}
.wh-move-row .what{font-size:12.5px;color:#5A4E42;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wh-move-row .val{font-size:13px;font-weight:800;text-align:end}
.wh-move-row .who{font-size:11.5px;color:#9C9082;text-align:end;white-space:nowrap}
.wh-move-row .note{grid-column:1/-1;font-size:11.5px;color:#8E8274;font-style:italic}

@media (max-width:980px){
    .whm-hint{display:none}
    .wh-grid{grid-template-columns:1fr}
    .wh-icons{grid-template-columns:repeat(4,1fr)}
    .wh-move-row{grid-template-columns:1fr auto}
    .wh-move-row .what,.wh-move-row .who{grid-column:1/-1}
}

/* v773 — the central warehouse: one dark node, a dark card on every branch's bar */
.whm-central{display:flex;align-items:center;gap:8px;border:1.5px solid #1C1712;background:#1C1712;color:#fff;border-radius:12px;
    padding:8px 14px;cursor:pointer;font-family:inherit}
.whm-central .nm{font-size:13px;font-weight:800}
.whm-central .meta{font-size:11.5px;color:#CFC5B8}
.whm-central.on{background:#FF5A00;border-color:#FF5A00}
.whm-node.central{border-color:#1C1712;background:#FFFBF5}
.whm-node.central .whm-ic{background:#1C1712;color:#fff}
.whm-body .nm em.c{background:#1C1712;color:#fff}
.wh-fixed{font-size:12.5px;font-weight:700;color:#5A4E42;border:1px dashed #D9CFC2;border-radius:10px;padding:9px 12px}
.wh-dialog-hint{font-size:11.5px;color:#8E8274;margin:2px 0 0 52px;line-height:1.4}

/* v774 — loyalty: the regulars. Four tiles up top, a guest card with a progress ring, the
   rules on the side, the leaderboard and the log. Tier colours: bronze, silver, gold. */
.ly{max-width:1180px;margin:0 auto;padding:2px 2px 40px}
.ly-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:14px}
.ly-stat{border:1px solid #EEE6DB;border-radius:18px;background:#fff;padding:14px 16px;display:flex;flex-direction:column;gap:2px;min-width:0}
.ly-stat .k{font-size:10.5px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274}
.ly-stat .v{font-size:24px;font-weight:800;color:#1C1712;line-height:1.1;font-variant-numeric:tabular-nums}
.ly-stat .v em{font-style:normal;font-size:12px;color:#8E8274;font-weight:700;margin-inline-start:2px}
.ly-stat .s{font-size:11.5px;color:#8E8274}
.ly-stat.chart{background:linear-gradient(135deg,#1C1712,#3A2A1C);border-color:#1C1712}
.ly-stat.chart .k{color:#CFC5B8}.ly-stat.chart .v{color:#fff}.ly-stat.chart .v em{color:#CFC5B8}
.ly-bars{display:flex;align-items:flex-end;gap:2px;height:38px;margin-top:8px}
.ly-bars .b{flex:1;background:#FF5A00;border-radius:2px 2px 0 0;position:relative;min-height:2px;opacity:.9}
.ly-bars .b i{position:absolute;left:0;right:0;bottom:0;background:#fff;opacity:.55;border-radius:2px}

.ly-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:14px;align-items:start}
.ly-side{display:flex;flex-direction:column;gap:14px}
.ly-card{border:1px solid #EEE6DB;border-radius:18px;padding:16px 18px;background:#fff}
.ly-card h3{font-size:14px;font-weight:800;margin:0 0 10px}
.ly-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}
.ly-head h3{margin:0}
.ly-empty{font-size:13px;color:#8E8274;margin:10px 0 2px}
.ly-hint{font-size:11px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274;margin:12px 0 6px}

.ly-search{display:flex;align-items:center;gap:8px;border:1.5px solid #E3D9CC;border-radius:14px;padding:8px 12px;color:#8E8274}
.ly-search:focus-within{border-color:#FF5A00}
.ly-search input{flex:1;border:0;outline:none;font-size:14px;font-family:inherit;background:none;color:#1C1712}
.ly-hits,.ly-top{display:flex;flex-direction:column;margin-top:8px}
.ly-hit{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:8px 6px;border:0;border-top:1px solid #F5EFE7;
    background:none;cursor:pointer;text-align:start;font-family:inherit;border-radius:10px}
.ly-top .ly-hit{grid-template-columns:22px auto 1fr auto}
.ly-hit:first-child{border-top:0}
.ly-hit:hover{background:#FFF6EF}
.ly-hit .rank{font-size:12px;font-weight:800;color:#B9AC9C;text-align:center}
.ly-hit .av,.ly-member .av{width:36px;height:36px;border-radius:12px;display:grid;place-items:center;font-size:12.5px;font-weight:800;color:#fff;background:#B87333}
.av.tier-silver{background:#8E9AA6}.av.tier-gold{background:#D4A017}
.ly-hit .nm{font-size:13.5px;font-weight:800;color:#1C1712;display:flex;flex-direction:column;min-width:0}
.ly-hit .nm small{font-size:11.5px;font-weight:600;color:#8E8274;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ly-hit .pt{font-size:14px;font-weight:800;color:#1C1712;font-variant-numeric:tabular-nums}
.ly-hit .pt em{font-style:normal;font-size:10.5px;color:#8E8274;margin-inline-start:2px}

.ly-member{position:relative;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center;margin-top:12px;padding:16px;
    border-radius:18px;background:linear-gradient(135deg,#FFF6EF,#FFFBF7);border:1.5px solid #FFD9BF}
.ly-member.tier-silver{background:linear-gradient(135deg,#F1F3F5,#FBFCFD);border-color:#D5DBE1}
.ly-member.tier-gold{background:linear-gradient(135deg,#FFF4D6,#FFFBEF);border-color:#F0D27A}
.ly-member .back{position:absolute;top:10px;inset-inline-end:10px;width:28px;height:28px;border-radius:9px;border:1px solid #EEE6DB;background:#fff;
    cursor:pointer;color:#8E8274;font-size:18px;line-height:1;font-family:inherit}
.ly-member .ring{--p:0;width:112px;height:112px;border-radius:50%;display:grid;place-items:center;position:relative;
    background:conic-gradient(#FF5A00 calc(var(--p)*1%),#F0E6DA 0)}
.ly-member.tier-silver .ring{background:conic-gradient(#5C6B7A calc(var(--p)*1%),#E3E7EB 0)}
.ly-member.tier-gold .ring{background:conic-gradient(#D4A017 calc(var(--p)*1%),#F3E6BE 0)}
.ly-member .ring::before{content:"";position:absolute;inset:9px;border-radius:50%;background:#fff}
.ly-member .ring .n,.ly-member .ring .u{position:relative}
.ly-member .ring .n{font-size:26px;font-weight:800;color:#1C1712;line-height:1;font-variant-numeric:tabular-nums}
.ly-member .ring .u{font-size:10.5px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#8E8274;margin-top:3px}
.ly-member .who{min-width:0}
.ly-member .nm{font-size:17px;font-weight:800;color:#1C1712;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ly-member .nm em.tier{font-style:normal;font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;border-radius:6px;padding:2px 7px;background:#B87333;color:#fff}
.ly-member.tier-silver .nm em.tier{background:#8E9AA6}.ly-member.tier-gold .nm em.tier{background:#D4A017}
.ly-member .ph{font-size:12.5px;color:#8E8274;margin-top:1px}
.ly-member .facts{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:8px;font-size:12px;color:#6B5D4F}
.ly-member .facts b{color:#1C1712}
.ly-member .next{margin-top:8px;font-size:12.5px;font-weight:700;color:#C44300;display:flex;align-items:center;gap:6px}

.ly-actions{display:grid;grid-template-columns:1fr;gap:6px;margin-top:6px}
.ly-act .row{display:flex;align-items:center;gap:8px}
.ly-act input{width:110px;border:1.5px solid #E3D9CC;border-radius:11px;padding:8px 10px;font-size:14px;font-weight:700;font-family:inherit;text-align:end}
.ly-act input.why{flex:1;text-align:start;font-weight:600;font-size:13px}
.ly-act input:focus{outline:none;border-color:#FF5A00}
.ly-act .sym{font-size:12.5px;font-weight:800;color:#8E8274}
.ly-act .go{margin-inline-start:auto;border:0;background:#1C1712;color:#fff;border-radius:11px;padding:9px 16px;font-size:13px;font-weight:800;cursor:pointer;font-family:inherit;
    display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.ly-act .go:hover{background:#FF5A00}
.ly-act .go:disabled{opacity:.35;cursor:default;background:#1C1712}
.ly-act .go.gift{background:#FF5A00;width:100%;justify-content:center;margin:0}
.ly-act .go.gift:hover{background:#C44300}
.ly-act .go.plain{width:40px;padding:9px 0;justify-content:center;margin:0}

.ly-log{display:flex;flex-direction:column;max-height:320px;overflow:auto}
.ly-log.wide{max-height:none}
.ly-ev{display:grid;grid-template-columns:64px 1fr auto;gap:10px;align-items:center;padding:7px 0;border-top:1px solid #F5EFE7;font-size:12.5px}
.ly-ev:first-child{border-top:0}
.ly-ev .pts{font-weight:800;font-variant-numeric:tabular-nums;color:#1E7A3C}
.ly-ev.redeem .pts{color:#C44300}.ly-ev.adjust .pts{color:#5A4E42}.ly-ev.welcome .pts{color:#6B2E8F}
.ly-ev .what{color:#5A4E42;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ly-ev .what b{color:#1C1712;margin:0 3px}
.ly-ev .what small{color:#8E8274;margin-inline-start:4px}
.ly-ev .who{font-size:11px;color:#9C9082;white-space:nowrap}

.ly-switch{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:800;color:#8E8274;cursor:pointer;user-select:none}
.ly-switch input{display:none}
.ly-switch span{width:38px;height:22px;border-radius:999px;background:#E3D9CC;position:relative;transition:background .15s}
.ly-switch span::after{content:"";position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:transform .15s}
.ly-switch.on{color:#1E7A3C}.ly-switch.on span{background:#1E7A3C}.ly-switch.on span::after{transform:translateX(16px)}
.ly-rule{display:grid;grid-template-columns:110px 1fr;gap:10px;align-items:center;padding:8px 0;border-top:1px solid #F5EFE7;font-size:12.5px;font-weight:700;color:#5A4E42}
.ly-rule:first-of-type{border-top:0}
.ly-rule .in{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.ly-rule input{width:74px;border:1.5px solid #E3D9CC;border-radius:10px;padding:6px 8px;font-size:13px;font-weight:800;font-family:inherit;text-align:end}
.ly-rule input:focus{outline:none;border-color:#FF5A00}
.ly-rule em{font-style:normal;font-size:12px;color:#8E8274;font-weight:700}
.ly-rule .tiers b{font-size:10.5px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;border-radius:6px;padding:2px 7px;color:#fff}
.ly-rule .t-silver{background:#8E9AA6}.ly-rule .t-gold{background:#D4A017}
.ly-preview{margin:10px 0;padding:10px 12px;border-radius:12px;background:#FFF6EF;color:#C44300;font-size:12.5px;font-weight:700;line-height:1.4}
.ly-auto{display:flex;gap:6px;align-items:flex-start;margin:10px 0 0;font-size:11.5px;color:#8E8274;line-height:1.4}

@media (max-width:980px){
    .ly-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
    .ly-grid{grid-template-columns:1fr}
    .ly-member{grid-template-columns:1fr;justify-items:center;text-align:center}
    .ly-member .nm{justify-content:center}.ly-member .facts,.ly-member .next{justify-content:center}
    .ly-ev{grid-template-columns:56px 1fr}.ly-ev .who{grid-column:2}
}

/* v775 — loyalty in motion. Cards rise in one after another (--i), numbers count up from
   the script, bars grow, the ring fills through a registered --p, a ready reward breathes,
   a handed-out reward pops. Insight strip: nearly-there and sleeping guests with a
   WhatsApp nudge. Reduced motion switches every animation off. */
@property --p{syntax:"<number>";inherits:false;initial-value:0}
.ly .rv{animation:ly-rise .55s cubic-bezier(.16,1,.3,1) both;animation-delay:calc(var(--i,0)*70ms)}
@keyframes ly-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.ly-stat{transition:transform .25s,box-shadow .25s}
.ly-stat:hover{transform:translateY(-2px);box-shadow:0 14px 30px -18px rgba(28,23,18,.35)}
.ly-stat .v{font-variant-numeric:tabular-nums}
.ly-tiermix{display:flex;height:6px;border-radius:999px;overflow:hidden;background:#F0E6DA;margin-top:8px}
.ly-tiermix i{display:block;height:100%;transition:width .9s cubic-bezier(.16,1,.3,1)}
.t-bronze{background:#B87333}.t-silver{background:#8E9AA6}.t-gold{background:#D4A017}
.ly-stat .legend{display:flex;align-items:center;gap:4px;font-size:11px;color:#8E8274;margin-top:5px}
.ly-stat .legend b{width:8px;height:8px;border-radius:50%;display:inline-block;margin-inline-start:6px}
.ly-stat .legend b:first-child{margin-inline-start:0}
.ly-bars .b{transform-origin:bottom;animation:ly-grow .7s cubic-bezier(.16,1,.3,1) both;animation-delay:calc(var(--i,0)*18ms + .3s)}
@keyframes ly-grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}

.ly-insights{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:14px}
.ly-insights:has(.ly-insight:only-child){grid-template-columns:1fr}
.ly-insight{border-radius:18px;padding:14px 16px;border:1px solid transparent;position:relative;overflow:hidden}
.ly-insight.almost{background:linear-gradient(135deg,#FFF1E6,#FFF9F4);border-color:#FFD9BF}
.ly-insight.sleep{background:linear-gradient(135deg,#EEF0F6,#F8F9FC);border-color:#D9DEE8}
.ly-insight .ih{display:flex;align-items:center;gap:8px}
.ly-insight .ih h4{margin:0;font-size:13.5px;font-weight:800;color:#1C1712}
.ly-insight.almost .ih .mud-icon-root{color:#FF5A00}.ly-insight.sleep .ih .mud-icon-root{color:#3D4A6B}
.ly-insight .ih .n{margin-inline-start:auto;font-size:12px;font-weight:800;background:#1C1712;color:#fff;border-radius:999px;padding:2px 9px}
.ly-insight p{margin:4px 0 10px;font-size:12px;color:#6B5D4F}
.ly-insight .chips{display:flex;flex-wrap:wrap;gap:8px}
.ly-chip{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(28,23,18,.08);background:#fff;border-radius:999px;padding:5px 6px 5px 5px;
    cursor:pointer;font-family:inherit;text-align:start;transition:transform .2s,box-shadow .2s}
.ly-chip:hover{transform:translateY(-1px);box-shadow:0 8px 18px -12px rgba(28,23,18,.5)}
.ly-chip .av{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:10.5px;font-weight:800;color:#fff;background:#B87333}
.ly-chip .t{display:flex;flex-direction:column;font-size:12.5px;font-weight:800;color:#1C1712;line-height:1.15}
.ly-chip .t small{font-size:10.5px;font-weight:700;color:#8E8274}
.ly-chip .wa{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#E9F5EC;color:#1E7A3C;transition:background .15s,color .15s}
.ly-chip .wa:hover{background:#1E7A3C;color:#fff}
.ly-chip .wa .mud-icon-root{font-size:16px;width:16px;height:16px}

.ly-search{transition:box-shadow .2s,border-color .2s}
.ly-search:focus-within{box-shadow:0 0 0 4px #FFE9DB}
.ly-search .spin{width:14px;height:14px;border:2px solid #F0E6DA;border-top-color:#FF5A00;border-radius:50%;animation:ly-spin .7s linear infinite}
@keyframes ly-spin{to{transform:rotate(360deg)}}
.ly-empty-art{display:flex;flex-direction:column;align-items:center;gap:10px;padding:28px 10px 18px;color:#8E8274;text-align:center;font-size:13px}
.ly-empty-art .orb{width:64px;height:64px;border-radius:50%;display:grid;place-items:center;color:#FF5A00;background:radial-gradient(circle at 30% 30%,#FFF1E6,#FFD9BF);
    animation:ly-float 3.2s ease-in-out infinite;box-shadow:0 14px 30px -16px rgba(255,90,0,.6)}
.ly-empty-art .orb .mud-icon-root{font-size:30px;width:30px;height:30px}
@keyframes ly-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
.ly-empty-art p{max-width:300px;margin:0}

.ly-member{overflow:hidden;animation:ly-rise .5s cubic-bezier(.16,1,.3,1) both}
.ly-member .glow{position:absolute;inset:-40%;background:radial-gradient(circle at 20% 30%,rgba(255,90,0,.14),transparent 45%);pointer-events:none}
.ly-member.tier-silver .glow{background:radial-gradient(circle at 20% 30%,rgba(92,107,122,.16),transparent 45%)}
.ly-member.tier-gold .glow{background:radial-gradient(circle at 20% 30%,rgba(212,160,23,.22),transparent 45%)}
.ly-member .ring{transition:--p 1.1s cubic-bezier(.16,1,.3,1)}
.ly-member .ring::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:2px solid transparent;opacity:0}
.ly-member.ready .ring::after{border-color:#FF5A00;animation:ly-breathe 1.8s ease-in-out infinite}
.ly-member.tier-gold.ready .ring::after{border-color:#D4A017}
@keyframes ly-breathe{0%,100%{opacity:.15;transform:scale(1)}50%{opacity:.7;transform:scale(1.06)}}
.ly-member .nm em.tier{position:relative;overflow:hidden}
.ly-member .nm em.tier::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.55) 50%,transparent 70%);
    transform:translateX(-120%);animation:ly-shine 3.4s ease-in-out infinite}
@keyframes ly-shine{0%{transform:translateX(-120%)}40%,100%{transform:translateX(120%)}}
.ly-member.pop{animation:ly-pop .6s cubic-bezier(.16,1,.3,1)}
@keyframes ly-pop{0%{transform:scale(1)}30%{transform:scale(1.025)}100%{transform:scale(1)}}
.ly-member .ph span{color:#B9AC9C}
.ly-member .tierbar{position:relative;height:18px;border-radius:999px;background:rgba(28,23,18,.06);margin-top:10px;overflow:hidden}
.ly-member .tierbar i{position:absolute;inset:0 auto 0 0;background:linear-gradient(90deg,#8E9AA6,#B7C1CB);border-radius:999px;transition:width 1s cubic-bezier(.16,1,.3,1)}
.ly-member.tier-silver .tierbar i{background:linear-gradient(90deg,#D4A017,#F0D27A)}
.ly-member .tierbar span{position:relative;font-size:10.5px;font-weight:800;color:#1C1712;line-height:18px;padding:0 9px}
.ly-confetti{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:3}
.ly-act .go{transition:background .15s,transform .15s}
.ly-act .go:not(:disabled):active{transform:scale(.97)}
.ly-act .go.gift.live{animation:ly-glow 2s ease-in-out infinite}
@keyframes ly-glow{0%,100%{box-shadow:0 0 0 0 rgba(255,90,0,0)}50%{box-shadow:0 10px 26px -6px rgba(255,90,0,.6)}}
.ly-walink{margin-top:8px;border:1px solid #CFE7D6;background:#F3FAF5;color:#1E7A3C;border-radius:11px;padding:8px 12px;font-size:12.5px;font-weight:800;
    cursor:pointer;font-family:inherit;display:inline-flex;align-items:center;gap:6px;transition:background .15s}
.ly-walink:hover{background:#1E7A3C;color:#fff;border-color:#1E7A3C}
.ly-hits .ly-hit.rv{animation-delay:calc(var(--i,0)*40ms)}
.ly-hit{transition:background .15s,transform .15s}
.ly-hit:hover{transform:translateX(2px)}

.ly-podium{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;align-items:end;margin:4px 0 10px}
.ly-podium .step{border:0;background:none;cursor:pointer;font-family:inherit;display:flex;flex-direction:column;align-items:center;gap:4px;padding:0}
.ly-podium .step .av{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;font-size:13px;font-weight:800;color:#fff;background:#B87333;
    box-shadow:0 8px 18px -10px rgba(28,23,18,.6);transition:transform .2s}
.ly-podium .step:hover .av{transform:scale(1.08)}
.ly-podium .step .nm{font-size:11.5px;font-weight:800;color:#1C1712;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ly-podium .step .pt{font-size:11px;color:#8E8274;font-weight:700}
.ly-podium .step .bar{width:100%;border-radius:10px 10px 0 0;display:grid;place-items:center;color:#fff;font-weight:800;font-size:13px;
    transform-origin:bottom;animation:ly-grow .8s cubic-bezier(.16,1,.3,1) both .25s}
.ly-podium .s1{order:2}.ly-podium .s2{order:1}.ly-podium .s3{order:3}
.ly-podium .s1 .bar{height:54px;background:linear-gradient(180deg,#FF5A00,#C44300)}
.ly-podium .s2 .bar{height:38px;background:linear-gradient(180deg,#8E9AA6,#6B7885)}
.ly-podium .s3 .bar{height:28px;background:linear-gradient(180deg,#C99A5B,#B87333)}
.ly-podium .s1 .av{width:48px;height:48px;font-size:15px}

@media (max-width:980px){
    .ly-insights{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){
    .ly .rv,.ly-bars .b,.ly-member,.ly-member.pop,.ly-podium .step .bar,.ly-empty-art .orb,.ly-member .nm em.tier::after,
    .ly-member.ready .ring::after,.ly-act .go.gift.live{animation:none!important}
    .ly-member .ring,.ly-tiermix i,.ly-member .tierbar i{transition:none!important}
}

/* v776 — loyalty: the left column stacks the guest finder and the activity log, so the two
   columns fill the same height; recent guests wait under the search box. */
.ly-main{display:flex;flex-direction:column;gap:14px;min-width:0}
.ly-main .ly-log.wide{max-height:520px;overflow:auto}
.ly-hits{margin-top:4px}

/* v777 — loyalty: the guest list is compact and scrolls inside the card */
.ly-hits{max-height:268px;overflow:auto;padding-inline-end:4px;scrollbar-width:thin}
.ly-hits .ly-hit{padding:5px 6px;gap:8px}
.ly-hits .ly-hit .av{width:30px;height:30px;border-radius:10px;font-size:11px}
