/* CTA band */
.mf-pos-band{margin-top:48px;border-radius:24px;padding:36px 30px;background:linear-gradient(135deg,#1C1712 0%,#3A2A1C 60%,#5A3418 100%);color:#fff;display:grid;grid-template-columns:1.3fr 1fr;gap:24px;align-items:center;position:relative;overflow:hidden}
